// 解析健康检查API的返回结果
const health = $input.item.json;

// 计算整体健康度
let healthStatus = 'healthy';
let healthEmoji = '✅';
let healthColor = '🟢';

const total = health.summary.total;
const passed = health.summary.passed;
const passRate = (passed / total * 100).toFixed(1);

if (passRate < 70) {
  healthStatus = 'critical';
  healthEmoji = '❌';
  healthColor = '🔴';
} else if (passRate < 90) {
  healthStatus = 'degraded';
  healthEmoji = '⚠️';
  healthColor = '🟡';
}

// 提取各数据源状态
const etf = health.sources.etf;
const index = health.sources.index;
const warmup = health.sources.warmup;
const lifecycle = health.sources.lifecycle;

// 构建详细报告
const report = {
  timestamp: health.timestamp,
  checkTime: $json.checkTime,
  overall: {
    status: healthStatus,
    emoji: healthEmoji,
    color: healthColor,
    passRate: passRate + '%',
    total: total,
    passed: passed,
    failed: total - passed
  },
  sources: {
    etf: {
      name: '📈 ETF数据',
      total: etf.total,
      ok: etf.ok,
      delayed: etf.delayed,
      failed: etf.failed,
      status: etf.failed > 0 ? '❌失败' : (etf.delayed > 0 ? '⚠️延迟' : '✅正常')
    },
    index: {
      name: '📊 指数数据',
      total: index.total,
      ok: index.ok,
      delayed: index.delayed,
      failed: index.failed,
      status: index.failed > 0 ? '❌失败' : (index.delayed > 0 ? '⚠️延迟' : '✅正常')
    },
    warmup: {
      name: '🔥 Warmup缓存',
      exists: warmup.exists,
      latestDate: warmup.latestDate,
      recordCount: warmup.recordCount,
      status: warmup.status === 'ok' ? '✅正常' : (warmup.status === 'stale' ? '⚠️过期' : '❌异常')
    },
    lifecycle: {
      name: '🎯 Lifecycle分析',
      exists: lifecycle.exists,
      latestDate: lifecycle.latestDate,
      itemsCount: lifecycle.itemsCount,
      status: lifecycle.status === 'ok' ? '✅正常' : (lifecycle.status === 'stale' ? '⚠️过期' : '❌异常')
    }
  }
};

return report;

